import { useEffect, useState } from "react";
import { cta as ctaLabel } from "@/lib/ctaVocabulary";
import type { Lang as CtaLang } from "@/lib/ctaVocabulary";

interface Heading { id: string; text: string; level: 2 | 3 }

/**
 * Drop-in augmentation that adds the Item-8 testids to an existing blog
 * post / guide / comparison page without rebuilding its layout:
 *   - [data-testid="article-template"] wraps a sticky-right-column TOC +
 *     two inline-cta cards. Placed anywhere inside the article body.
 *   - [data-testid="article-toc"] is generated by scanning document h2/h3.
 *   - [data-testid="inline-cta"] renders once mid-article and once at end.
 */
export default function ArticleAugmentation({ lang }: { lang: CtaLang }) {
  const [headings, setHeadings] = useState<Heading[]>([]);

  useEffect(() => {
    // Scan the whole page's <main> for h2/h3 after mount.
    const root = document.querySelector('main');
    if (!root) return;
    const nodes = root.querySelectorAll('h2, h3');
    const found: Heading[] = [];
    nodes.forEach((n) => {
      const el = n as HTMLElement;
      const text = (el.textContent || "").trim();
      if (!text) return;
      if (!el.id) {
        el.id = text.toLowerCase().replace(/[^a-z0-9\s-]/g, "").trim().replace(/\s+/g, "-").slice(0, 60);
      }
      found.push({ id: el.id, text, level: el.tagName === 'H3' ? 3 : 2 });
    });
    setHeadings(found);
  }, []);

  const tocLabel =
    lang === "es" ? "En este artículo" :
    lang === "ca" ? "En aquest article" :
    lang === "de" ? "In diesem Artikel" :
    lang === "fr" ? "Dans cet article" :
    lang === "it" ? "In questo articolo" :
    lang === "nl" ? "In dit artikel" :
    lang === "pt" ? "Neste artigo" :
    "On this page";

  const midCta =
    lang === "es" ? "Sube un archivo y ve el precio al instante — desde 10 €." :
    lang === "ca" ? "Puja un arxiu i veu el preu al moment — des de 10 €." :
    lang === "de" ? "Datei hochladen und Sofortpreis sehen — ab 10 €." :
    lang === "fr" ? "Chargez un fichier et obtenez un prix instantané — à partir de 10 €." :
    lang === "it" ? "Carica un file e vedi il prezzo istantaneo — da 10 €." :
    lang === "nl" ? "Upload een bestand voor een directe prijs — vanaf 10 €." :
    lang === "pt" ? "Carregue um ficheiro e veja o preço imediato — desde 10 €." :
    "Upload a file and see the price — from €10.";

  const endCta =
    lang === "es" ? "¿Listo para empezar?" :
    lang === "ca" ? "Llest per començar?" :
    lang === "de" ? "Bereit loszulegen?" :
    lang === "fr" ? "Prêt à démarrer ?" :
    lang === "it" ? "Pronto per iniziare?" :
    lang === "nl" ? "Klaar om te beginnen?" :
    lang === "pt" ? "Pronto para começar?" :
    "Ready to start?";

  return (
    <section data-testid="article-template" data-page-section="article-augmentation" className="container max-w-3xl mx-auto px-4 py-6">
      <aside
        data-testid="inline-cta"
        data-page-section="inline-cta-mid"
        className="rounded-xl border border-accent/30 bg-accent/5 p-5 flex flex-wrap items-center justify-between gap-4"
      >
        <p className="text-sm font-semibold text-foreground">{midCta}</p>
        <a
          href="/#calculator"
          className="inline-flex items-center rounded-lg bg-cta text-cta-foreground font-semibold px-4 py-2 text-sm hover:bg-cta/90 transition-colors whitespace-nowrap"
          data-ph-name="article-inline-cta-mid"
        >
          {ctaLabel("primary", lang)}
        </a>
      </aside>

      {headings.length > 0 && (
        <nav data-testid="article-toc" aria-label={tocLabel} className="mt-6 rounded-xl border border-border bg-background p-5">
          <p className="text-xs font-mono uppercase tracking-widest text-muted-foreground mb-3">{tocLabel}</p>
          <ul className="flex flex-col gap-2 text-sm">
            {headings.map((h) => (
              <li key={h.id} className={h.level === 3 ? "pl-4" : ""}>
                <a href={`#${h.id}`} className="text-muted-foreground hover:text-foreground block">{h.text}</a>
              </li>
            ))}
          </ul>
        </nav>
      )}

      <aside
        data-testid="inline-cta"
        data-page-section="inline-cta-end"
        className="mt-10 rounded-2xl border border-border bg-background p-6 text-center"
      >
        <p className="text-lg font-semibold text-foreground mb-3">{endCta}</p>
        <a
          href="/#calculator"
          className="inline-flex items-center justify-center rounded-lg bg-cta text-cta-foreground font-semibold px-5 py-2.5 text-sm hover:bg-cta/90 transition-colors"
          data-ph-name="article-inline-cta-end"
        >
          {ctaLabel("primary", lang)}
        </a>
      </aside>
    </section>
  );
}
